"""Outcome verification for the OpenDoc Q3 sync decision log task.

The stored document list is read from the browser Local Storage area through the
runtime controller.  Only the persisted document is compared with the outcome
the task declares: the document title, the heading and body lines, the agenda
items, and the rows of the inserted table.
"""

from __future__ import annotations

import html as html_module
import json
import re
from typing import Any, Mapping

from evaluators.cua_review.core.evaluation import BaseEvaluator, EvalResult, EvalStatus
from evaluators.cua_review.platforms.linux.local_storage import LOCAL_STORAGE_SOURCE

STATE_KEY = "opendoc.documents.v1"

PROFILE_DIRS = (
    "/home/user/.config/google-chrome/Default/Local Storage/leveldb",
    "/home/user/.config/chromium/Default/Local Storage/leveldb",
    "/home/user/.config/osomni-openapps/launch-opendoc/Default/Local Storage/leveldb",
)

TAG = re.compile(r"<[^>]+>")
ROW = re.compile(r"<tr[\s>].*?</tr>", re.I | re.S)
CELL = re.compile(r"<t[dh][\s>].*?</t[dh]>", re.I | re.S)


def _text(value: Any) -> str:
    return "" if value is None else str(value)


def _directories(params: Mapping[str, Any]) -> list[str]:
    """Return the Local Storage directories this task allows."""
    extra = (
        params.get("profile_dirs")
        or params.get("local_state_paths")
        or params.get("storage_dirs")
    )
    found: list[str] = []
    if isinstance(extra, (list, tuple)):
        for item in extra:
            text = str(item or "").strip()
            if text and text not in found:
                found.append(text)
    for item in PROFILE_DIRS:
        if item not in found:
            found.append(item)
    return found


def _read_document(controller: Any, key: str, directories: list[str]) -> tuple[Any, str]:
    """Return the stored OpenDoc document list and the directory it was read from."""
    for directory in directories:
        value: Any = None
        if controller is not None and hasattr(controller, "run_python_script"):
            program = (
                LOCAL_STORAGE_SOURCE
                + "\nprint(json.dumps(read_state(%s, %s), ensure_ascii=False))\n"
                % (json.dumps(directory), json.dumps(key))
            )
            try:
                payload = controller.run_python_script(program, timeout=60)
            except Exception:
                payload = None
            if isinstance(payload, Mapping):
                text = str(payload.get("stdout") or payload.get("output") or "").strip()
                if text:
                    try:
                        value = json.loads(text)
                    except ValueError:
                        value = None
        if value is None:
            try:
                from evaluators.cua_review.platforms.linux.local_storage import read_state

                value = read_state(directory, key)
            except Exception:
                value = None
        if isinstance(value, list):
            return value, directory
    return None, ""


def _blocks(html: Any) -> list[str]:
    plain = html_module.unescape(TAG.sub("\n", _text(html)))
    return [line.strip() for line in plain.split("\n") if line.strip()]


def _table_rows(html: Any) -> list[list[str]]:
    rows: list[list[str]] = []
    for raw in ROW.findall(_text(html)):
        cells = [html_module.unescape(TAG.sub("", cell)).strip() for cell in CELL.findall(raw)]
        if cells:
            rows.append(cells)
    return rows


def _row_present(rows: list[list[str]], wanted: list[str]) -> bool:
    return any(row[: len(wanted)] == wanted for row in rows)


class OpenDocDecisionLogEvaluator(BaseEvaluator):
    """Compare the stored OpenDoc document with the declared final outcome."""

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = dict(context.get("params") or {})
        controller = context.get("controller")
        key = str(params.get("storage_key") or STATE_KEY)
        title = _text(params.get("expected_title"))
        documents, source = _read_document(controller, key, _directories(params))

        checks: list[dict[str, Any]] = []
        metadata: dict[str, Any] = {
            "state_key": key,
            "source": source,
            "document_titles": [
                item.get("title") for item in (documents or []) if isinstance(item, Mapping)
            ],
            "checks": checks,
        }
        if not isinstance(documents, list) or not documents or not title:
            return EvalResult(
                status=EvalStatus.FAIL,
                message="the OpenDoc document is not present in browser Local Storage",
                metadata=metadata,
            )

        candidates = [
            item
            for item in documents
            if isinstance(item, Mapping) and _text(item.get("title")) == title
        ]
        checks.append(
            {
                "name": "document_title",
                "passed": bool(candidates),
                "expected": title,
                "actual": metadata["document_titles"],
            }
        )
        if not candidates:
            return EvalResult(
                status=EvalStatus.FAIL,
                message="the declared OpenDoc document title is not present: %s" % title,
                metadata=metadata,
            )

        document = candidates[0]
        html = _text(document.get("html"))
        blocks = _blocks(html)
        plain = "\n".join(blocks)
        rows = _table_rows(html)

        lines: list[tuple[str, str]] = [("main_heading", _text(params.get("main_heading")))]
        lines.append(("date_line", _text(params.get("date_line"))))
        lines.append(("owner_line", _text(params.get("owner_line"))))
        lines.append(("agenda_heading", _text(params.get("agenda_heading"))))
        for index, item in enumerate(params.get("agenda_items") or []):
            lines.append(("agenda_item.%d" % index, _text(item)))
        lines.append(("decision_heading", _text(params.get("decision_heading"))))
        for index, item in enumerate(params.get("decision_lines") or []):
            lines.append(("decision_line.%d" % index, _text(item)))

        for name, wanted in lines:
            if not wanted:
                continue
            present = wanted in blocks or wanted in plain
            checks.append(
                {
                    "name": name,
                    "passed": present,
                    "expected": wanted,
                    "actual": present,
                }
            )

        for index, wanted_row in enumerate(params.get("table_rows") or []):
            if not isinstance(wanted_row, (list, tuple)):
                continue
            expected_cells = [_text(cell) for cell in wanted_row]
            checks.append(
                {
                    "name": "table_row.%d" % index,
                    "passed": _row_present(rows, expected_cells),
                    "expected": expected_cells,
                    "actual": rows,
                }
            )

        failures = [item["name"] for item in checks if not item["passed"]]
        metadata["observed_rows"] = rows
        if not checks or failures:
            return EvalResult(
                status=EvalStatus.FAIL,
                message="the declared OpenDoc outcome is not present: %s"
                % ", ".join(failures[:8]),
                metadata=metadata,
            )
        return EvalResult(
            status=EvalStatus.PASS,
            message="the declared OpenDoc outcome is present",
            metadata=metadata,
        )
